"""test_boss_spec.py — data-driven behavioral validation of the Boss-Blind
layer against tools/boss_spec.json (the reference-doc §10 + §16 contract,
generated by tools/gen_boss_spec.py).

The static audit (tools/audit_bosses_static.py) guarantees STRUCTURE: the 28
keys, min-ante eligibility, the 5-boss Showdown pool, the Matador table, and
that each effect's implementing code matches the doc. This file guarantees
BEHAVIOR: every boss is actually selectable exactly when the doc allows it,
and the large-blind chip scaling matches the doc §16 multipliers. When a
row's expectation disagrees with the sim, the sim is wrong — fix the sim,
not the test. (Per-boss effect behavior is covered in test_boss_effects.py
and the Matador payouts in test_phase0.py TestMatador.)
"""
from __future__ import annotations

import json
import pathlib

import pytest

from balatro_sim.constants import BLIND_CHIPS
from balatro_sim.game import BOSS_MIN_ANTE, SHOWDOWN_BOSSES, BalatroGame
from balatro_sim.seed_rng import node_boss

ROOT = pathlib.Path(__file__).resolve().parents[3]
SPEC = json.load(open(ROOT / "tools" / "boss_spec.json", encoding="utf-8"))
BOSSES = SPEC["bosses"]


def _candidates(game: BalatroGame, ante: int) -> list[str]:
    """The boss pool `_select_boss(ante)` would draw from (fewest-appearances
    candidates), captured without consuming the pick."""
    captured: list[list[str]] = []
    game.rng.node(node_boss()).choice = (
        lambda seq: (captured.append(list(seq)), seq[0])[1])
    game._select_boss(ante)
    return captured[0] if captured else []


def _boss_target(game: BalatroGame, boss_key: str) -> int:
    """Prepare the next blind as `boss_key` at ante 1 and return its target."""
    game.ante = 1
    game.blind_idx = 2                       # Boss blind
    game.rng.node(node_boss()).choice = lambda seq: boss_key
    game._prepare_next_blind()
    return game.current_blind.chips_target


# ── Spec vs sim tables (structure, data-driven) ─────────────────────────────

@pytest.mark.parametrize("key", sorted(BOSSES), ids=lambda k: k)
def test_spec_matches_sim_tables(key):
    entry = BOSSES[key]
    assert key in BOSS_MIN_ANTE, f"{key} missing from BOSS_MIN_ANTE"
    assert BOSS_MIN_ANTE[key] == entry["min_ante"], \
        f"{key}: sim min-ante {BOSS_MIN_ANTE[key]} != doc {entry['min_ante']}"
    is_showdown = key in SHOWDOWN_BOSSES
    assert is_showdown == entry["finisher"], \
        f"{key}: showdown {is_showdown} != doc finisher {entry['finisher']}"


def test_spec_counts():
    assert len(BOSSES) == 28
    assert len(SPEC["matador"]) == 13
    assert len(SPEC["showdown"]) == 5
    assert all(k in BOSSES for k in SPEC["matador"])
    assert set(SPEC["showdown"]) == SHOWDOWN_BOSSES


# ── Selectability (behavior, data-driven) ───────────────────────────────────

@pytest.mark.parametrize("key", sorted(BOSSES), ids=lambda k: k)
def test_selectable_at_min_ante(key):
    ante = BOSSES[key]["min_ante"]
    g = BalatroGame(seed=11)
    assert key in _candidates(g, ante), \
        f"{key} not selectable at its min ante {ante}"


@pytest.mark.parametrize(
    "key", [k for k, e in BOSSES.items() if e["min_ante"] > 1],
    ids=lambda k: k)
def test_never_below_min_ante(key):
    ante = BOSSES[key]["min_ante"] - 1
    g = BalatroGame(seed=11)
    assert key not in _candidates(g, ante), \
        f"{key} selectable below its min ante {ante}"


@pytest.mark.parametrize("key", SPEC["showdown"], ids=lambda k: k)
def test_showdown_only_at_ante_8(key):
    g = BalatroGame(seed=11)
    assert key in _candidates(g, 8), f"{key} missing from the ante-8 pool"
    assert key not in _candidates(g, 7), \
        f"{key} selectable before ante 8"


# ── Large-blind scaling (§16, data-driven) ──────────────────────────────────

@pytest.mark.parametrize("key", sorted(SPEC["scaling"]), ids=lambda k: k)
def test_large_blind_scaling(key):
    base = BLIND_CHIPS[1][0]                 # ante-1 Small Blind base (1x)
    g = BalatroGame(seed=11)
    target = _boss_target(g, key)
    assert target == base * SPEC["scaling"][key], \
        f"{key}: target {target} != base {base} x {SPEC['scaling'][key]}"


# ── Matador list (doc integrity) ────────────────────────────────────────────

def test_matador_list_integrity():
    # The doc's 13 — the audit pins the game's matador decision block to this
    # exact set; here we just verify the list is internally consistent.
    matador = SPEC["matador"]
    assert len(matador) == len(set(matador)) == 13
    assert all(BOSSES[k]["min_ante"] <= 8 for k in matador)
    # Verdant Leaf is the only Showdown boss that pays Matador.
    showdown_matador = [k for k in matador if k in SPEC["showdown"]]
    assert showdown_matador == ["bl_verdant"]
